    group_by(year) %>%
    summarise(n_harvested = n(),
              bm_harvested = sum(weight)/1000,
              mean_wt = mean(weight), 
              sd_wt = sd(weight),
              mean_age = mean(age),
              sd_age = sd(age),
              mean_cond = mean(condition),
