    ungroup() %>%
    right_join(all_exp_years, by = "year") %>%
    replace_na(list(n_harvested = 0L,
                    bm_harvested = 0L,
                    mean_wt = NA,
                    sd_wt = NA,
                    mean_age = NA,
                    sd_age = NA,
                    mean_cond = NA,
